<template>
  <section class="obd-page">
    <RouterLink class="back-link" to="/garage">← Back to garage</RouterLink>
    <header class="page-heading"><div><span class="eyebrow">VEHICLE CONNECTION</span><h2>OBD Bluetooth test</h2><p>Connect a BLE ELM327-compatible adapter and send one command at a time.</p></div><span class="browser-badge">{{ browserName }}</span></header>
    <section class="connection-card">
      <div class="connection-status"><span class="status-dot" :class="state"></span><div><strong>{{ stateLabel }}</strong><small>{{ supportMessage }}</small></div></div>
      <div class="connection-actions"><button class="button button-primary" type="button" :disabled="!canConnect || state === 'connecting'" @click="connect">{{ state === 'connected' ? 'Connected' : state === 'connecting' ? 'Connecting…' : 'Connect adapter' }}</button><button v-if="state === 'connected'" class="button button-outline" type="button" @click="disconnect">Disconnect</button></div>
      <p v-if="device" class="device-line">{{ device.name }} <small>{{ device.id }}</small></p><p v-if="errorMessage" class="error-message">{{ errorMessage }}</p>
    </section>
    <section class="command-card"><div class="section-heading"><div><span class="eyebrow">RAW COMMAND</span><h3>Send ELM327 command</h3></div><span class="hint">Commands end with CR automatically</span></div><form class="command-form" @submit.prevent="sendCommand"><input v-model="command" :disabled="state !== 'connected' || sending" aria-label="OBD command" placeholder="010C" autocomplete="off" spellcheck="false" /><button class="button button-primary" type="submit" :disabled="state !== 'connected' || sending || !command.trim()">{{ sending ? 'Waiting…' : 'Send' }}</button></form><div class="quick-commands"><button v-for="item in quickCommands" :key="item.command" type="button" :disabled="state !== 'connected' || sending" @click="sendQuickCommand(item.command)"><code>{{ item.command }}</code><span>{{ item.label }}</span></button></div></section>
    <section class="log-card"><div class="section-heading"><div><span class="eyebrow">SESSION LOG</span><h3>Adapter responses</h3></div><button class="button button-outline" type="button" :disabled="!log.length" @click="log = []">Clear</button></div><div v-if="log.length" class="log-list"><article v-for="entry in log" :key="entry.id"><div><code>&gt; {{ entry.command }}</code><small>{{ entry.time }}</small></div><pre>{{ entry.response }}</pre></article></div><p v-else class="empty-copy">Connect adapter, then send ATZ, 0100, or 010C.</p></section>
    <aside class="notice"><strong>Safe test scope</strong><span>This screen sends raw commands only. Start with read commands. Avoid reset, clear-code, coding, and actuator commands.</span></aside>
  </section>
</template>

<script setup lang="ts">
import { computed, onBeforeUnmount, ref } from 'vue'
import { ObdBluetoothTransport, type ObdBluetoothDeviceInfo, type ObdConnectionState } from '../services/obdBluetooth'

const transport = new ObdBluetoothTransport(); const state = ref<ObdConnectionState>('disconnected'); const device = ref<ObdBluetoothDeviceInfo | null>(null); const command = ref('010C'); const sending = ref(false); const errorMessage = ref(''); const log = ref<{ id: number; command: string; response: string; time: string }[]>([])
const quickCommands = [{ command: 'ATZ', label: 'Reset adapter' }, { command: '0100', label: 'Supported PIDs' }, { command: '010C', label: 'Engine RPM' }, { command: '010D', label: 'Vehicle speed' }, { command: '0105', label: 'Coolant temperature' }, { command: '03', label: 'Stored trouble codes' }]
const browserName = computed(() => navigator.userAgent.includes('Brave') ? 'Brave detected' : 'Chromium browser'); const canConnect = computed(() => window.isSecureContext && 'bluetooth' in navigator); const stateLabel = computed(() => state.value === 'connected' ? 'Adapter connected' : state.value === 'connecting' ? 'Waiting for adapter' : 'Adapter disconnected'); const supportMessage = computed(() => !window.isSecureContext ? 'Use HTTPS or localhost.' : !('bluetooth' in navigator) ? 'Web Bluetooth unavailable. Use Brave or Chrome.' : state.value === 'connected' ? 'Ready for commands.' : 'Click Connect, then choose your BLE adapter.')
transport.onStateChange = (next) => { state.value = next }; transport.onDeviceChange = (next) => { device.value = next }
async function connect() { errorMessage.value = ''; try { await transport.connect() } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Bluetooth connection failed'; state.value = 'disconnected' } }
async function disconnect() { await transport.disconnect() }
async function sendQuickCommand(value: string) { command.value = value; await sendCommand() }
async function sendCommand() { if (!command.value.trim() || state.value !== 'connected') return; const sent = command.value.trim(); sending.value = true; errorMessage.value = ''; try { const response = await transport.send(sent); log.value.unshift({ id: Date.now(), command: sent, response, time: new Date().toLocaleTimeString() }) } catch (error) { errorMessage.value = error instanceof Error ? error.message : 'Command failed' } finally { sending.value = false } }
onBeforeUnmount(() => { void transport.disconnect() })
</script>

<style scoped>
.obd-page { max-width: 900px; }.back-link { color: var(--muted); text-decoration: none; font-size: 13px; }.page-heading { display: flex; justify-content: space-between; align-items: flex-end; gap: 24px; margin: 34px 0 26px; }.page-heading h2 { font: 700 34px 'Space Grotesk'; letter-spacing: -1.2px; margin: 9px 0 5px; }.page-heading p { color: var(--muted); margin: 0; }.eyebrow { color: var(--muted); font-size: 10px; letter-spacing: 1.5px; font-weight: 700; }.browser-badge, .hint { color: var(--muted); font-size: 12px; }.connection-card, .command-card, .log-card, .notice { margin-top: 18px; padding: 22px; border: 1px solid var(--line); border-radius: 9px; background: var(--surface); box-shadow: var(--shadow); }.connection-status, .connection-actions, .section-heading, .command-form { display: flex; align-items: center; justify-content: space-between; gap: 14px; }.connection-status { justify-content: flex-start; }.connection-status strong, .connection-status small { display: block; }.connection-status small { color: var(--muted); margin-top: 4px; }.status-dot { width: 10px; height: 10px; border-radius: 50%; background: var(--danger); }.status-dot.connected { background: #6c9b34; }.status-dot.connecting { background: #d39a39; }.device-line, .error-message { font-size: 12px; margin: 16px 0 0; }.device-line small { color: var(--muted); margin-left: 8px; }.error-message { color: var(--danger); }.button { border: 0; border-radius: 7px; padding: 11px 15px; font-weight: 700; cursor: pointer; }.button-primary { background: var(--accent); color: var(--accent-ink); }.button-outline { border: 1px solid var(--line); background: transparent; color: var(--brand-soft); }.button:disabled { cursor: not-allowed; opacity: .5; }.section-heading { align-items: flex-end; margin-bottom: 18px; }.section-heading h3 { margin: 7px 0 0; font: 600 22px 'Space Grotesk'; }.command-form input { min-width: 0; flex: 1; border: 1px solid var(--line); border-radius: 6px; padding: 11px; color: var(--ink); background: var(--surface); font-family: monospace; text-transform: uppercase; }.quick-commands { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 14px; }.quick-commands button { display: grid; gap: 3px; border: 1px solid var(--line); border-radius: 6px; padding: 8px 10px; background: var(--surface-muted); color: var(--brand-soft); cursor: pointer; text-align: left; }.quick-commands button span { color: var(--muted); font-size: 10px; }.quick-commands button:disabled { cursor: not-allowed; opacity: .5; }.log-list { display: grid; gap: 10px; }.log-list article { border-top: 1px solid var(--line); padding-top: 10px; }.log-list article div { display: flex; justify-content: space-between; gap: 12px; }.log-list small { color: var(--muted); }.log-list pre { overflow: auto; margin: 8px 0 0; padding: 10px; border-radius: 6px; background: var(--surface-muted); white-space: pre-wrap; }.empty-copy { color: var(--muted); }.notice { display: grid; gap: 5px; color: var(--muted); font-size: 12px; }.notice strong { color: var(--brand-soft); }
@media (max-width: 680px) { .page-heading, .connection-status, .connection-actions, .section-heading, .command-form { align-items: stretch; flex-direction: column; }.connection-actions, .command-form { width: 100%; }.connection-actions .button, .command-form .button { width: 100%; text-align: center; }.browser-badge { align-self: flex-start; } }
</style>
